using System;
using System.IO;
using System.Net;
using System.Threading.Tasks;
using System.Collections.Generic;
using System.Web.Script.Serialization;
namespace FssLauncher {
 public sealed class StudioConnection {
  int controlPort;public string GameState="NOT LAUNCHED";public bool GameLoginComplete,GameFrontend,GameStandalone;public int GameProcessId;
  public StudioState State=StudioState.Stopped;public string Error="",Instance="",BackendUrl="";public Dictionary<string,string> Services=new Dictionary<string,string>();
  public async Task Refresh(string root){
   bool verifiedControl=false;try{
    string descriptor=Path.Combine(root,"Gameserver/Studio/studio-control.json");if(!File.Exists(descriptor)){State=StudioState.Stopped;Instance="";Services.Clear();return;}
    var json=new JavaScriptSerializer();var info=json.Deserialize<Dictionary<string,object>>(File.ReadAllText(descriptor));
    int port=Convert.ToInt32(info["port"]);string expected=Convert.ToString(info["instance"]);if(port<1024||port>65535||Convert.ToString(info["protocol"])!="FSS.STUDIO/1")throw new IOException("Unsupported Studio connection.");
    string challenge=Guid.NewGuid().ToString("N");var data=await Task.Run(delegate{
     var request=(HttpWebRequest)WebRequest.Create("http://127.0.0.1:"+port+"/health?challenge="+challenge);request.Proxy=null;request.Timeout=2500;request.ReadWriteTimeout=2500;
     using(var response=request.GetResponse())using(var reader=new StreamReader(response.GetResponseStream()))return json.Deserialize<Dictionary<string,object>>(reader.ReadToEnd());
    });
    if(Convert.ToString(data["protocol"])!="FSS.STUDIO/1"||Convert.ToString(data["instance"])!=expected||Convert.ToString(data["challenge"])!=challenge||!Path.GetFullPath(Convert.ToString(data["installation"])).TrimEnd(Path.DirectorySeparatorChar,Path.AltDirectorySeparatorChar).Equals(Path.GetFullPath(root).TrimEnd(Path.DirectorySeparatorChar,Path.AltDirectorySeparatorChar),StringComparison.OrdinalIgnoreCase))throw new IOException("Studio connection identity did not verify.");
    verifiedControl=true;Instance=expected;controlPort=port;
    if(Convert.ToString(data["stage"])=="STARTING"&&String.IsNullOrEmpty(Convert.ToString(data["backendUrl"]))){State=StudioState.Starting;Instance=expected;Error="Server Studio is starting its local services...";Services.Clear();return;}
    Uri backend;if(!Uri.TryCreate(Convert.ToString(data["backendUrl"]),UriKind.Absolute,out backend)||!backend.IsLoopback||backend.Scheme!="http"||backend.UserInfo!=""||backend.AbsolutePath!="/")throw new IOException("Studio supplied an invalid local account service.");BackendUrl=backend.GetLeftPart(UriPartial.Authority);
    var values=(Dictionary<string,object>)data["services"];bool healthy=Convert.ToBoolean(data["online"]);string selected=CoreStudio.LauncherMatchSettings.Load(root).BackendUrl;if(!String.IsNullOrEmpty(selected)){BackendUrl=selected;var remote=await Task.Run(delegate{var request=(HttpWebRequest)WebRequest.Create(selected+"/studio/services");request.Proxy=null;request.Timeout=4000;request.ReadWriteTimeout=4000;using(var response=request.GetResponse())using(var reader=new StreamReader(response.GetResponseStream()))return json.Deserialize<Dictionary<string,object>>(reader.ReadToEnd());});values=new Dictionary<string,object>();string[] fields={"backend","auth","matchmaking","tcp","globalChat"};string[] names={"BACKEND","AUTH","MATCHMAKING","TCP","GLOBAL CHAT"};healthy=Convert.ToString(data["stage"])!="FAILED";for(int i=0;i<fields.Length;i++){object value;values[names[i]]=remote.TryGetValue(fields[i],out value)&&(Convert.ToString(value)=="online"||Convert.ToString(value)=="listening")?"ONLINE":"OFFLINE";}values["GAME SERVICES"]=values["BACKEND"];}
    Services.Clear();foreach(string name in new[]{"BACKEND","AUTH","MATCHMAKING","TCP","GLOBAL CHAT","GAME SERVICES"}){object value;string status=values.TryGetValue(name,out value)?Convert.ToString(value):"OFFLINE";Services[name]=status;healthy&=status=="ONLINE";}
    controlPort=port;object game;if(data.TryGetValue("game",out game)&&game is Dictionary<string,object>){var value=(Dictionary<string,object>)game;GameState=Convert.ToString(value["state"]);GameLoginComplete=Convert.ToBoolean(value["loginComplete"]);GameFrontend=Convert.ToBoolean(value["frontend"]);GameStandalone=Convert.ToBoolean(value["standalone"]);GameProcessId=Convert.ToInt32(value["processId"]);}
    string stage=Convert.ToString(data["stage"]);State=healthy?StudioState.Online:stage=="STARTING"?StudioState.Starting:StudioState.Error;Instance=expected;object detail;Error=healthy?"":data.TryGetValue("error",out detail)&&!String.IsNullOrEmpty(Convert.ToString(detail))?Convert.ToString(detail):stage=="STARTING"?"Connecting to Server Studio...":"A required Studio service is offline.";
   }catch(Exception error){State=verifiedControl?StudioState.Error:StudioState.Stopped;if(!verifiedControl)Instance="";Services.Clear();Error=(verifiedControl?"Selected backend is not responding: ":"Server Studio is not responding: ")+error.Message;}
  }
  public async Task RevealStudio(){if(String.IsNullOrEmpty(Instance))throw new IOException("Studio is still starting. Please retry shortly.");string identity=Instance;int port=controlPort;await Task.Run(delegate{var request=(HttpWebRequest)WebRequest.Create("http://127.0.0.1:"+port+"/studio/ui");request.Proxy=null;request.Method="POST";request.ContentType="application/json";request.Headers["X-FSS-Instance"]=identity;request.Timeout=5000;byte[] body=System.Text.Encoding.UTF8.GetBytes("{}");request.ContentLength=body.Length;using(var stream=request.GetRequestStream())stream.Write(body,0,body.Length);using(var response=request.GetResponse()){};});}
  public async Task Launch(string executable,string code){if(State!=StudioState.Online)throw new IOException("Studio must be online before launching.");string identity=Instance;int port=controlPort;await Task.Run(delegate{var request=(HttpWebRequest)WebRequest.Create("http://127.0.0.1:"+port+"/launch");request.Proxy=null;request.Method="POST";request.ContentType="application/json";request.Headers["X-FSS-Instance"]=identity;request.Timeout=45000;request.ReadWriteTimeout=45000;byte[] data=System.Text.Encoding.UTF8.GetBytes(new JavaScriptSerializer().Serialize(new{executable=executable,code=code,backendUrl=BackendUrl}));request.ContentLength=data.Length;using(var stream=request.GetRequestStream())stream.Write(data,0,data.Length);try{using(var response=request.GetResponse()){};}catch(WebException error){if(error.Response!=null){using(var response=error.Response)using(var reader=new StreamReader(response.GetResponseStream())){var result=new JavaScriptSerializer().Deserialize<Dictionary<string,object>>(reader.ReadToEnd());object message;if(result.TryGetValue("error",out message))throw new IOException(Convert.ToString(message));}}throw new IOException("Studio disconnected before launch completed.");}});}
 }
}
